import sys, os, json
sys.path.insert(0,'/opt/tools')
import numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from PIL import Image

class Control:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=s.data;self.k=mujoco.MjData(self.m);self.bid=self.m.body('palmworld').id
  self.jp=np.zeros((3,self.m.nv));self.jr=self.jp.copy()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  if q is None:q=self.s.targets.copy()
  else:q=q.copy()
  for _ in range(80):
   self.k.qpos[:]=self.d.qpos;self.k.qpos[self.s._jq]=q;mujoco.mj_kinematics(self.m,self.k);mujoco.mj_comPos(self.m,self.k)
   ep=p-self.k.xpos[self.bid];er=Rot.from_matrix(R@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec();e=np.r_[ep,er]
   if np.linalg.norm(e)<1e-6:break
   mujoco.mj_jacBody(self.m,self.k,self.jp,self.jr,self.bid);J=np.vstack([self.jp[:,:7],self.jr[:,:7]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]=np.clip(q[:7]+dq*min(1,.15/max(abs(dq))),self.s.lower[:7]+.001,self.s.upper[:7]-.001)
  return q
 def move(self,p,R=None,hand=None,n=120):
  p0,R0=self.pose()
  if R is None:R=R0
  dr=Rot.from_matrix(R@R0.T).as_rotvec();q0=self.s.targets.copy()
  for i in range(n):
   a=(i+1)/n;a=a*a*(3-2*a);qi=self.ik(p0+(p-p0)*a,Rot.from_rotvec(dr*a).as_matrix()@R0)
   if hand is not None:qi[7:]=q0[7:]*(1-a)+np.asarray(hand)*a
   self.s.step(qi)
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.s.targets)
 def hand(self,hand,n=120):
  q0=self.s.targets.copy()
  for i in range(n):
   a=(i+1)/n;qi=q0.copy();qi[7:]=q0[7:]*(1-a)+np.asarray(hand)*a;self.s.step(qi)
 def snap(self,name):
  Image.fromarray(self.s.render_grid(size=(640,480))).save('/app/output/'+name+'.png')
 def report(self,name):
  print(name, 'step',self.s.steps,'object',self.s.state()['object_pos'],self.s.state()['object_quat_wxyz'],'palm',self.pose()[0],'progress',self.s.progress(),flush=True)
  contacts={}
  for c in self.d.contact:
   b1=self.m.geom_bodyid[c.geom1];b2=self.m.geom_bodyid[c.geom2]
   if self.s._obj in [b1,b2]:
    b=b1 if b2==self.s._obj else b2;nm=self.m.body(b).name
    f=np.zeros(6);mujoco.mj_contactForce(self.m,self.d,list(self.d.contact).index(c) if False else 0,f)
    contacts[nm]=contacts.get(nm,0)+1
  print('contacts',contacts,'hand q',self.d.qpos[self.s._jq][7:],flush=True)

def grip(flex=(.8,1.2,.7),thumb=(1.5,0,1.,0,.7)):
 h=np.zeros(22);h[:5]=thumb
 for j in [5,9,13,18]:h[j]=flex[0];h[j+2]=flex[1];h[j+3]=flex[2]
 return h

if __name__=='__main__':
 par=json.loads(sys.argv[1]) if len(sys.argv)>1 else {}
 s=rcb_dtb.Session();s.record_start();c=Control(s);c.hold(60);p,R=c.pose();
 c.move(p+np.array(par.get('offset',[.02,.01,-.075])),R,n=180);c.snap('approach');c.report('approach')
 c.hand(grip(par.get('flex',[.8,1.2,.7]),par.get('thumb',[1.5,0,1.,0,.7])),180);c.hold(60);c.snap('grasp');c.report('grasp')
 p,R=c.pose();c.move(p+np.array([0,0,.11]),R,n=240);c.hold(120);c.snap('lift');c.report('lift')
 A=s.record_stop();s.save_trajectory(A,'/app/output/test.npz');
 if s._renderer:s._renderer.close()
PY
